after.content:
$ErrorActionPreference = "Stop"
$env:NO_PROXY = "127.0.0.1,localhost"
$env:no_proxy = $env:NO_PROXY

& "$PSScriptRoot\verify-stage4.ps1"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

corepack pnpm install --frozen-lockfile --offline
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
corepack pnpm check:generated
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
corepack pnpm exec buf lint protocol/relay
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
& "$PSScriptRoot\..\gradlew.bat" :ji-relay-protocol:test :ji-relay-server:test :ji-host-core:test :ji-host-sqlite:test :ji-host-web:test --offline --no-daemon
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
corepack pnpm --filter '@ji/web-app' test
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
corepack pnpm --filter '@ji/web-app' build
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
docker compose -p ji-relay -f deploy/relay/compose.yaml config --quiet
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
Write-Output "STAGE5_LOCAL_GATE_OK"
